// Отримаємо всі вхідні айтеми
const inputItems = $input.all();

// Тут будемо збирати всі домени
const domains = [];

for (const item of inputItems) {
	// 1) Якщо вже є поле item.json.domain
	if (item.json.domain) {
		domains.push(item.json.domain);
		continue;
	}

	// 2) Якщо відповідь така, як у HTTP Request:
	// item.json._data – це обʼєкт з доменами всередині
	if (item.json._data && typeof item.json._data === 'object') {
		for (const key of Object.keys(item.json._data)) {
			const entry = item.json._data[key];
			if (entry && entry.domain) {
				domains.push(entry.domain);
			}
		}
	}
}

// Повертаємо ОДИН item з усіма доменами
return [
	{
		json: {
			domains,
		},
	},
];

